			target.position += Vector3(speed[0],speed[1],speed[2]) * dt
			target.rotation.y += deg_to_rad(float(inputs.target_motion.yaw_degrees_s)) * dt
	candidate.step(dt)

func sample() -> Dictionary:
	return candidate.sample()
